    // Delete element at index 3
    for(int i = 3; i < n-1; i++) {
        arr[i] = arr[i+1];
    }
    n--;

    cout << endl;
    // Print: 10 20 25 40 50
    for(int i = 0; i < n; i++) {
        cout << arr[i] << " ";
    }
    return 0;
}

