#include <iostream>
#include <vector>
#include <climits>
using namespace std;

// Maximum sum subarray of size k
int maxSumSubarray(vector<int>& arr, int k) {
    int n = arr.size();
    int windowSum = 0, maxSum = INT_MIN;

    for(int i = 0; i < n; i++) {
        windowSum += arr[i];

        if(i >= k - 1) {
            maxSum = max(maxSum, windowSum);
            windowSum -= arr[i - k + 1];
        }
    }
    return maxSum;
}

int main() {
    vector<int> arr = {2, 1, 5, 1, 3, 2};
    int k = 3;
    cout << "Max sum of subarray size " << k << ": ";
    cout << maxSumSubarray(arr, k) << endl;  // 9 (5+1+3)
    return 0;
}

