#include <stdio.h>
#include <limits.h>

int maxSumSubarray(int arr[], int n, int k) {
    int windowSum = 0, maxSum = INT_MIN;
    for (int i = 0; i < n; i++) {
        windowSum += arr[i];
        if (i >= k - 1) {
            if (windowSum > maxSum) maxSum = windowSum;
            windowSum -= arr[i - k + 1];
        }
    }
    return maxSum;
}

